/* ---------------- func_000E8E84 (src/pilot/mcard/func_000E8E84.c) ---------------- */
/* FAKEMATCH: the no-op `c &= 0xff;` after the byte load only reproduces the in-place andi. */
/* SJIS (0x82 / 0x81 lead) -> ASCII name copy, max 32 chars. The outer loop is a goto loop (a for loop lets loop.c
   hoist the 0x82/0x81 compare constants); `c &= 0xff` is a no-op on the byte but is what leaves the in-place andi. */
void func_000E8E84(unsigned char *src, unsigned char *dst)
{
    unsigned char i;
    unsigned char j;
    int c;
    int o;
    int k;
    MC_SJIS *t;

    i = 0;
    t = D_000ED7E8;
loop:
    o = 0x3F;
    c = *src++;
    c &= 0xff;
    if (c == 0)
        goto end;
    if (c == 0x82) {
        c = *src++;
        if ((unsigned char)(c - 0x4F) < 10 || (unsigned char)(c - 0x60) < 26)
            o = c - 0x1F;
        else if ((unsigned char)(c + 0x7F) < 26)
            o = c - 0x20;
    } else if (c == 0x81) {
        c = *src++;
        k = c;
        for (j = 0; j < 33; j++) {
            if (k == t[j].k)
                o = t[j].v;
        }
    }
    *dst++ = o;
    i++;
    if (i < 32)
        goto loop;
end:
    *dst = 0;
}

/* ---------------- func_000E8F68 (src/pilot/mcard/func_000E8F68.c) ---------------- */
/* ASCII -> SJIS name copy (inverse of func_000E8E84) */
void func_000E8F68(unsigned char *src, unsigned char *dst)
{
    int i;
    int c;
    unsigned int t; /* offset into the punctuation table (low byte of code) */
    int k;
    unsigned int code;

    k = 0xFF;
    memset(dst, 0, 32);
    for (i = 0; i < 31; i++) {
        c = *src++;
        if (c == 0)
            break;
        code = 0;
        if (c >= 0x20 && c < 0x30)
            code = 1;
        else if (c >= '0' && c <= '9')
            k = 0;
        else if (c >= 0x3A && c < 0x41)
            code = 0xB;
        else if (c >= 'A' && c <= 'Z')
            k = 1;
        else if (c >= 0x5B && c < 0x61)
            code = 0x25;
        else if (c >= 'a' && c <= 'z')
            k = 2;
        else if (c >= 0x7B && c < 0x7F)
            code = 0x3F;
        else {
            *dst++ = 0x81;
            *dst = 0x40;
            dst++;
            continue;
        }
        t = code & 0xFF;
        if (t) {
            t += 0x1F;
            code = *(unsigned short *)&D_000ED7E8[c - t].k;
        }
        else
            code = D_000ED7DC[k].base + c - D_000ED7DC[k].first;
        *dst++ = code >> 8;
        *dst = code;
        dst++;
    }
}

